# Must be a positive compile-time constant.
TILE_J = 64


@proc
def kernel_ludcmp(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    # invD[i] holds 1 / A[i, i] once row i of U has been finalized.
    # This replaces many divisions by cheaper multiplications.
    invD: DATA_TYPE[n]

    # Shared scalar temporaries.
    w: DATA_TYPE
    jj: size

    # ---------------------------------------------------------------
    # Phase 1: In-place LU factorization (Doolittle, no pivoting)
    #          with cached reciprocals of diagonal pivots.
    #
    # After this phase:
    #   - For j < i: A[i, j] holds L(i, j) (unit diagonal is implicit).
    #   - For j >= i: A[i, j] holds U(i, j).
    #   - invD[i] = 1 / U(i, i).
    # ---------------------------------------------------------------
    for i in seq(0, n):

        # ---------------------------
        # 1a. Strict lower triangle L
        #     L(i, j) for 0 <= j < i:
        #
        #     L(i, j) = ( A[i, j]
        #                 - sum_{k=0..j-1} L(i, k) * U(k, j) ) / U(j, j)
        #
        # We use invD[j] = 1 / U(j, j) (computed when row j was processed)
        # to avoid performing the division here.
        # ---------------------------
        for j in seq(0, i):
            w = A[i, j]
            for k in seq(0, j):
                w = w - A[i, k] * A[k, j]
            w = w * invD[j]
            A[i, j] = w

        # ---------------------------
        # 1b. Upper triangle U, j >= i
        #
        #     U(i, j) = A[i, j] - sum_{k=0..i-1} L(i, k) * U(k, j)
        #
        # We tile the column dimension j to improve cache locality when
        # accessing A[k, j] across multiple k and to encourage SIMD.
        # ---------------------------
        for JJ in seq(0, (n - i + TILE_J - 1) / TILE_J):
            for j in seq(0, TILE_J):
                jj = i + JJ * TILE_J + j
                if jj < n:
                    w = A[i, jj]
                    for k in seq(0, i):
                        w = w - A[i, k] * A[k, jj]
                    A[i, jj] = w

        # ---------------------------
        # 1c. Cache reciprocal of pivot U(i, i)
        #
        #     invD[i] = 1 / U(i, i).
        #
        # This is later used in:
        #   - L-updates of rows r > i via invD[i]
        #   - backward substitution when solving U * x = y.
        # ---------------------------
        invD[i] = 1.0 / A[i, i]

    # ---------------------------------------------------------------
    # Phase 2: Forward substitution to solve L * y = b.
    #
    # L has unit diagonal and is stored below the main diagonal in A.
    # For i = 0..n-1:
    #   y[i] = b[i] - sum_{j=0..i-1} L(i, j) * y[j].
    # ---------------------------------------------------------------
    for i in seq(0, n):
