    # Phase 3: Backward substitution to solve U * x = y.
    #
    # Original C code:
    #   for (i = n-1; i >= 0; i--) {
    #     w = y[i];
    #     for (j = i+1; j < n; j++)
    #         w -= A[i][j] * x[j];
    #     x[i] = w / A[i][i];
    #   }
    #
    # We rewrite it as a forward loop in i_rev with the same semantics:
    #   i0 = n - 1 - i_rev
    # and use invD[i0] instead of an explicit division.
    # ---------------------------------------------------------------
    for i_rev in seq(0, n):
        # Physical row index counting from the last row backwards.
        w = y[n - 1 - i_rev]

        # j runs from i0 + 1 up to n - 1.
        for j in seq(n - i_rev, n):
            w = w - A[n - 1 - i_rev, j] * x[j]

        # Use cached reciprocal of the diagonal pivot.
        x[n - 1 - i_rev] = w * invD[n - 1 - i_rev]
